def make_1px_borders(grid):
    result = [row[:] for row in grid]
    nrows, ncols = len(grid), len(grid[0])

    # Find all hollow rectangles and make them 1px
    regions_found = set()

    for r in range(nrows):
        for c in range(ncols):
            if grid[r][c] == 2:
                # Find bounding box of all 2s connected
                from collections import deque
                q = deque([(r, c)])
                visited = {(r, c)}
                while q:
                    rr, cc = q.popleft()
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < nrows and 0 <= nc < ncols:
                            if grid[nr][nc] == 2 and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                q.append((nr, nc))

                # Find min/max boundaries 
                min_r, max_r = min(rr for rr,cc in visited), max(rr for rr,cc in visited)
                min_c, max_c = min(cc for rr,cc in visited), max(cc for rr,cc in visited)

                # Store this region if not already found
                key = (min_r, min_c, max_r, max_c)
                if key not in regions_found:
                    regions_found.add(key)
                    # Fill interior with 0s (keeping only 1px border)
                    for rr in range(min_r + 1, max_r):
                        for cc in range(min_c + 1, max_c):
                            result[rr][cc] = 0

    return result

