def fill_all_rects(grid):
    result = [row[:] for row in grid]
    nrows, ncols = len(grid), len(grid[0])
    used = [[False] * ncols for _ in range(nrows)]

    for r_start in range(nrows):
        for c_start in range(ncols):
            if grid[r_start][c_start] == 2 and not used[r_start][c_start]:
                # Find connected component
                from collections import deque
                q = deque([(r_start, c_start)])
                visited = {(r_start, c_start)}

                while q:
                    rr, cc = q.popleft()
                    used[rr][cc] = True
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < nrows and 0 <= nc < ncols:
                            if grid[nr][nc] == 2 and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                q.append((nr, nc))

                # Find bounding box
                min_r, max_r = min(rr for rr, _ in visited), max(rr for rr, _ in visited)
                min_c, max_c = min(cc for _, cc in visited), max(cc for _, cc in visited)

                # Fill entire bounding box
                for rr in range(min_r, max_r + 1):
                    for cc in range(min_c, max_c + 1):
                        result[rr][cc] = 2

    return result

